const rules = {
  fullName: {
    required: true,
    validate(value) {
      if (!value.trim()) return "Full name is required.";
      if (value.trim().length < 2) return "Please enter your full name (at least 2 characters).";
      return null;
    },
  },
  email: {
    required: true,
    validate(value) {
      if (!value.trim()) return "Email address is required.";
      // RFC-ish email check
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(value.trim()))
        return "Please enter a valid email address (e.g. you@example.com).";
      return null;
    },
  },
  phone: {
    required: false,
    validate(value) {
      if (!value.trim()) return null; // optional
      // Accept +1 (555) 123-4567 | (555) 123-4567 | 555-123-4567 | 10-15 digit variants
      if (!/^\+?[\d\s\-().]{7,20}$/.test(value.trim()))
        return "Please enter a valid phone number (e.g. (555) 123-4567).";
      return null;
    },
  },
};

// ── Field component logic ───────────────────────────────────────
class Field {
  /**
   * @param {HTMLInputElement} input
   * @param {HTMLElement} errorEl
   */
  constructor(input, errorEl) {
    this.input = input;
    this.errorEl = errorEl;
    this.name = input.id;
    this.dirty = false;

    input.addEventListener("blur", () => {
      this.dirty = true;
      this.validate();
    });

    input.addEventListener("input", () => {
      if (this.dirty) this.validate();
    });
  }

  validate() {
    const rule = rules[this.name];
    if (!rule) return true;
    const error = rule.validate(this.input.value);
    this._setError(error);
    return error === null;
  }

  _setError(message) {
    if (message) {
      this.input.setAttribute("aria-invalid", "true");
      this.errorEl.textContent = "";
      // Rebuild error with icon
      const icon = createErrorIcon();
      const text = document.createTextNode(message);
      this.errorEl.appendChild(icon);
      this.errorEl.appendChild(text);
      this.errorEl.classList.add("visible");
    } else {
      this.input.setAttribute("aria-invalid", "false");
      this.errorEl.classList.remove("visible");
      this.errorEl.textContent = "";
    }
  }

  markDirty() {
    this.dirty = true;
  }

  focus() {
    this.input.focus();
  }
}

// ── SVG helpers ─────────────────────────────────────────────────
function createErrorIcon() {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("aria-hidden", "true");
  svg.setAttribute("focusable", "false");
  svg.setAttribute("width", "14");
  svg.setAttribute("height", "14");
  svg.setAttribute("viewBox", "0 0 20 20");
  svg.setAttribute("fill", "currentColor");
  svg.classList.add("error-icon");
  svg.innerHTML = `<path fill-rule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-8-5a.75.75 0 01.75.75v4.5a.75.75 0 01-1.5 0v-4.5A.75.75 0 0110 5zm0 10a1 1 0 100-2 1 1 0 000 2z" clip-rule="evenodd"/>`;
  return svg;
}

// ── Form component ──────────────────────────────────────────────
function ContactForm() {
  const form = document.getElementById("contact-form");
  const successBanner = document.getElementById("success-banner");
  const submitBtn = document.getElementById("btn-submit");

  const fields = {
    fullName: new Field(
      document.getElementById("fullName"),
      document.getElementById("fullName-error")
    ),
    email: new Field(
      document.getElementById("email"),
      document.getElementById("email-error")
    ),
    phone: new Field(
      document.getElementById("phone"),
      document.getElementById("phone-error")
    ),
  };

